                '\u0631\u0648\u0632 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646: \xab\u0627\u0645\u0631\u0648\u0632\xbb\u060c \xab\u0641\u0631\u062f\u0627\xbb\u060c \xab\u067e\u0633\u200c\u0641\u0631\u062f\u0627\xbb \u06cc\u0627 \xab\u0631\u0648\u0632 \u062f\u06cc\u06af\u0631\xbb. \u0633\u0627\u0639\u062a \u0631\u0627 \u0628\u0627 \u06a9\u0634\u06cc\u062f\u0646 \u0627\u0646\u06af\u0634\u062a \u0631\u0648\u06cc \u0686\u0631\u062e \u0633\u0627\u0639\u062a \u0628\u0627\u0644\u0627 \u0648 \u067e\u0627\u06cc\u06cc\u0646 \u0628\u0628\u0631 \u0648 \u0630\u062e\u06cc\u0631\u0647 \u06a9\u0646.',
                '\u0633\u0631 \u0648\u0642\u062a \u0631\u0648\u06cc \u06af\u0648\u0634\u06cc \u062e\u0628\u0631\u062a \u0645\u06cc\u200c\u06a9\u0646\u06cc\u0645 \u0648 \u06cc\u0627\u062f\u0622\u0648\u0631\u06cc \u0628\u0647 \xab\u0627\u0631\u0633\u0627\u0644\u200c\u0634\u062f\u0647\xbb \u0645\u06cc\u200c\u0631\u0648\u062f. \u0627\u06af\u0631 \u06a9\u0627\u0631 \u0647\u0646\u0648\u0632 \u0645\u0627\u0646\u062f\u0647\u060c \xab\u062f\u0648\u0628\u0627\u0631\u0647 \u06cc\u0627\u062f\u0645 \u0628\u0646\u062f\u0627\u0632\xbb \u0631\u0627 \u0628\u0632\u0646 \u0648 \u0632\u0645\u0627\u0646 \u062a\u0627\u0632\u0647 \u0628\u06af\u0630\u0627\u0631.',
