                '\u0642\u06cc\u0645\u062a \u0647\u0631 \u0631\u062f\u06cc\u0641 \u0631\u0627 \u0628\u0646\u0648\u06cc\u0633\u061b \u0646\u0627\u0645 \u0631\u0627 \u0647\u0645 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc \u0639\u0648\u0636 \u06a9\u0646\u06cc. \u0647\u0631 \u06a9\u0627\u0644\u0627 \u062a\u0627 \u06f5 \u0642\u06cc\u0645\u062a \u062f\u0627\u0631\u062f: \xab\u0642\u06cc\u0645\u062a \u0641\u0631\u0648\u0634\xbb \u0648 \u06f4 \u0642\u06cc\u0645\u062a \u062f\u06cc\u06af\u0631. \u0628\u0627 \xab\xd7\xbb \u06a9\u0646\u0627\u0631 \u0631\u062f\u06cc\u0641\u060c \u0622\u0646 \u0642\u06cc\u0645\u062a \u0628\u0631\u062f\u0627\u0634\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.',
                '\xab\u0630\u062e\u06cc\u0631\u0647 \u06a9\u0627\u0644\u0627\xbb \u0631\u0627 \u0628\u0632\u0646\u061b \u0642\u06cc\u0645\u062a\u200c\u0647\u0627 \u062f\u0631 \u0632\u0628\u0627\u0646\u0647\u0654 \xab\u0642\u06cc\u0645\u062a\u200c\u0647\u0627\xbb \u0647\u0645 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.',
                '\u0645\u0648\u0642\u0639 \u0641\u0631\u0648\u0634 \u062f\u0631 \xab\u062b\u0628\u062a \u0633\u0631\u06cc\u0639\xbb (\xab\u0641\u0631\u0648\u062e\u062a\u0647 \u0634\u062f\xbb)\u060c \u0628\u0627 \u0628\u0627\u0631\u06a9\u062f \u06cc\u0627 \u0628\u0627 \u0635\u062f\u0627\u060c \u062f\u06a9\u0645\u0647\u0654 \u06a9\u0648\u0686\u06a9 \xab\u0642\u06cc\u0645\u062a \u0641\u0631\u0648\u0634\xbb \u0632\u06cc\u0631 \u0642\u06cc\u0645\u062a \u0631\u0627 \u0628\u0632\u0646 \u0648 \u062f\u0631 \xab\u06a9\u062f\u0627\u0645 \u0642\u06cc\u0645\u062a\u061f\xbb \u0642\u06cc\u0645\u062a \u062f\u06cc\u06af\u0631 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646.',
